using System.Data; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class DefaultPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetAnnouncements() { var table = DbHelper.ExecuteDataTable(@"SELECT TOP 6 AnnouncementID, Title, Content, CONVERT(varchar(10), StartDate, 120) AS StartDate FROM Announcements WHERE IsActive = 1 AND (StartDate IS NULL OR StartDate <= GETDATE()) AND (EndDate IS NULL OR EndDate >= GETDATE()) ORDER BY StartDate DESC, AnnouncementID DESC", CommandType.Text); return new { success = true, data = DbHelper.ToDictionaryList(table) }; } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetLanguages() { return new { success = true, data = LocalizationHelper.GetLanguages() }; } } }
